'use strict';
const L = require('./lib.cjs');
const { icon, page, badge, notice, crumbs, pageHead, field, selectField, skeletonRows, emptyState, reviewNote, esc, fmt, RATES, MAT } = L;

function dlg(show, title, ic, body, foot, { wide = false, danger = false, role = 'dialog' } = {}) {
  const id = 'dlg-' + show.split(' ')[0];
  return `<div class="backdrop" data-show="${show}" hidden><div class="modal${wide ? ' is-wide' : ''}" role="${role}" aria-modal="true" aria-labelledby="${id}-t"><div class="modal-head">${icon(ic, 20)}<h2 id="${id}-t" class="t-sub">${title}</h2></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div></div></div>`;
}
const search = (ph, id = 'q') => `<div class="field" style="flex:1 1 260px"><label class="field-label" for="${id}">Search</label><div class="input-icon">${icon('search', 18)}<input class="input" id="${id}" type="search" placeholder="${ph}"></div></div>`;
const loadingBlock = (rows = 5, cols = 4) => `<div data-show="loading" hidden aria-busy="true"><p class="sr-only" role="status">Loading</p>${skeletonRows(rows, cols)}</div>`;
const errorBlock = (what) => `<div data-show="error" hidden>${emptyState({ ic: 'alert', title: `We could not load ${what}`, text: 'Check your connection and try again. Nothing was changed.', action: '<button class="btn btn-secondary" type="button">' + icon('undo', 18) + ' Try again</button>' })}</div>`;
const iconBtn = (ic, label) => `<button class="btn btn-secondary btn-icon" type="button" aria-label="${label}" style="width:36px;height:36px">${icon(ic, 16)}</button>`;
const lockTag = (t) => `<span class="badge badge-neutral" title="${t}">${icon('lock', 12)} System</span>`;

/* ============================ SCR-11 Process master ============================ */
const PROC = [
  ['Cutting-Rate-per-Sec', '₹ per second', 0.47, 'AL'], ['Bending-Rate-per-stroke', '₹ per stroke', 3.15, 'AM'], ['Drilling-Tapping-Rate', '₹ per hole', 2.35, 'AN'],
  ['Welding-rate-per-kg', '₹ per kg', 13.6, 'AO'], ['Dip-Galvanizing-Cost-per-kg', '₹ per kg', 9.4, 'AQ'], ['Primer-rate-per-sqft', '₹ per sq ft', 6.85, 'AR'],
  ['Shot-Blasting-rate-per-kg', '₹ per kg', 4.3, 'AS'], ['Polishing-rate-per-sqin', '₹ per sq in', 0.93, 'AT'], ['Plating-rate-per-sqin', '₹ per sq in', 1.35, null], ['Powder-rate-per-sqft', '₹ per sq ft', 8.1, 'AV'],
  ['Foam Cost', '₹ per sq ft', 21.5, 'AW'], ['Soft-Anodize-rate-per-sqin', '₹ per sq in', 1.75, 'AX'], ['OH Profit %', '%', 11, 'BD'], ['Transport %', '%', 2.5, 'BF'], ['Inspection & Packing %', '%', 3, 'BE'],
];
function scr11() {
  const rows = PROC.map((p, i) => `<tr><td class="t-strong">${esc(p[0])}</td><td class="t-muted">${p[1]}</td><td class="num">${fmt(p[2])}${p[1] === '%' ? ' %' : ''}</td><td>${p[3] ? `<span class="col-tag is-out">${p[3]}</span>` : '<span class="t-muted">None yet</span>'}</td><td class="num">${[2, 0, 1, 0, 0, 0, 0, 3, 0, 0, 0, 0, 1, 0, 0][i]}</td><td class="t-right col-actions"><div class="row" style="justify-content:flex-end;gap:var(--s-2)">${iconBtn('edit', 'Edit ' + p[0])}<a class="btn btn-secondary btn-icon" style="width:36px;height:36px" href="#state=blocked" aria-label="Delete ${esc(p[0])}">${icon('trash', 16)}</a></div></td></tr>`).join('');
  const cards = PROC.slice(0, 4).map((p) => `<article class="card task-card"><div class="row-nowrap"><span class="t-strong">${esc(p[0])}</span><span class="spacer"></span><span class="col-tag is-out">${p[3]}</span></div><div class="t-sub t-num">${fmt(p[2])} <span class="t-label t-muted">${p[1]}</span></div><div class="row"><button class="btn btn-secondary" type="button">${icon('edit', 18)} Edit</button><button class="btn btn-secondary" type="button">${icon('trash', 18)} Delete</button></div></article>`).join('');
  const main = `<main class="page" id="main">
   ${pageHead({ title: 'Process master', sub: 'Default rates. Every customer starts with these values and can have its own.', actions: `<button class="btn btn-primary" type="button">${icon('plus', 18)} Add rate</button>` })}
   <div data-show="saved" hidden>${notice('success', 'checkc', 'Cutting-Rate-per-Sec saved. The change is in the audit log.', 'status')}</div>
   <section class="card"><div class="card-body row" style="align-items:flex-end">${search('Rate name')}</div>
    <div data-show="default saved sync add blocked" class="table-wrap is-master hide-mobile"><table class="table"><caption class="sr-only">Process master rates</caption><thead><tr><th scope="col">Rate name</th><th scope="col">Unit</th><th scope="col" class="num">Default value</th><th scope="col">Used in</th><th scope="col" class="num">Customers with own value</th><th scope="col" class="col-actions"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows}</tbody></table></div>
    <div data-show="default saved sync add blocked" class="stack show-mobile" style="padding:var(--s-4)">${cards}</div>
    ${loadingBlock(6, 5)}${errorBlock('the rates')}
    <div data-show="nomatch" hidden>${emptyState({ ic: 'search', title: 'No rate matches "buffing"', text: 'Check the spelling, or add it as a new rate.', action: '<button class="btn btn-primary" type="button">' + icon('plus', 18) + ' Add rate</button>' })}</div></section>
   ${dlg('add', 'Add rate', 'plus', `${field({ id: 'pm-name', label: 'Rate name', value: 'Buffing-rate-per-sqin', hint: 'Used in formulas exactly as written. Names ending in % are typed as whole percentages: 12 means 12%.' })}${selectField({ id: 'pm-unit', label: 'Unit', options: ['₹ per second', '₹ per stroke', '₹ per hole', '₹ per kg', '₹ per sq ft', '₹ per sq in', '%'], value: '₹ per sq in', required: true })}${field({ id: 'pm-val', label: 'Default value', unit: '₹', mode: 'decimal', value: '', error: 'Enter a number, 0 or more, with up to 2 decimals.' })}<p class="t-label t-muted">Adding a rate adds it to every customer with this default.</p>`, `<button class="btn btn-secondary" type="button">Cancel</button><button class="btn btn-primary" type="button">Add rate</button>`)}
   ${dlg('sync', 'Cutting-Rate-per-Sec changed from 0.47 to 0.52', 'alert', `<p class="t-body">17 customers had 0.47 and now have 0.52. <strong>3 customers have a different value.</strong> Choose what to do for each one.</p>
    <div class="table-wrap"><table class="table"><caption class="sr-only">Customers whose value differs from the old default</caption><thead><tr><th scope="col">Customer</th><th scope="col" class="num">Current value</th><th scope="col">Choice</th></tr></thead><tbody>
     ${[['Marlow Agro Systems', '0.50'], ['Orchid Rail Works', '0.45'], ['Ridgeline Pumps', '0.55']].map((c, i) => `<tr><th scope="row" style="text-transform:none;letter-spacing:0;font-size:var(--fs-body);color:var(--ink);background:none">${c[0]}</th><td class="num">${c[1]}</td><td><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">${c[0]}</legend><div class="row"><label class="check"><input type="radio" name="s${i}" ${i === 0 ? 'checked' : ''}> Apply 0.52</label><label class="check"><input type="radio" name="s${i}" ${i === 0 ? '' : 'checked'}> Keep ${c[1]}</label></div></fieldset></td></tr>`).join('')}</tbody></table></div>`, `<button class="btn btn-secondary" type="button">Keep all 3</button><button class="btn btn-secondary" type="button">Apply to all 3</button><button class="btn btn-primary" type="button">Save choices</button>`, { wide: true })}
   ${dlg('blocked', 'This rate is used by a formula', 'alert', `<p class="t-body"><strong>Cutting-Rate-per-Sec</strong> cannot be deleted while a formula uses it. Change those formulas first.</p><div class="table-wrap"><table class="table"><thead><tr><th scope="col">Column</th><th scope="col">Field</th><th scope="col">Formula</th></tr></thead><tbody><tr><td><span class="col-tag is-out">AL</span></td><td>Cutting Cost</td><td class="formula">P * Cutting-Rate-per-Sec</td></tr></tbody></table></div>`, `<a class="btn btn-secondary" href="SCR-17.html">Go to Fields and formulas</a><button class="btn btn-primary" type="button">Close</button>`, { role: 'alertdialog' })}
   ${reviewNote('Release 1. The change prompt (FR-014) is R1+: if it is not reached, the Admin edits customer rates by hand until Release 2. Names and units are the list given by the delivery lead (OQ-UX-07, rate-unit half closed). Plating-rate-per-sqin is used by no formula yet: Plating Cost stays typed in (Q-42). Deleting an unused rate shows a simple confirm dialog (same pattern as the delete-part dialog). Phone: rows become cards.')}
  </main>`;
  return page({ id: 'SCR-11', file: 'SCR-11.html', name: 'Process master', title: 'Process master', desc: 'Manage the default process rates used in every cost calculation.', role: 'admin', active: 'process', states: ['default', 'saved:Saved', 'sync:Customers differ (R1+)', 'add:Add rate', 'blocked:Delete blocked', 'loading', 'nomatch:No match', 'error'], roleLabel: 'Admin', release: 'R1; sync R1+', frs: 'FR-012, 014', body: main });
}

/* ============================ SCR-12 Customers ============================ */
const CUST = [['Brightwater Controls', '+91 98765 00001', 'purchasing@brightwater.example.test', 3], ['Marlow Agro Systems', '+91 98765 00002', 'quotes@marlow.example.test', 1], ['Orchid Rail Works', '+91 98765 00003', 'rfq@orchid.example.test', 2], ['Ridgeline Pumps', '+91 98765 00004', 'estimating@ridgeline.example.test', 0], ['Tamarind Switchgear', '+91 98765 00005', 'buying@tamarind.example.test', 0]];
function scr12() {
  const rows = CUST.map((c) => `<tr><td class="t-strong"><a href="#state=edit">${c[0]}</a></td><td>${c[1]}</td><td class="hide-md">${c[2]}</td><td class="num">${c[3] ? c[3] + ' differ' : '<span class="t-muted">All default</span>'}</td><td class="t-right col-actions"><div class="row" style="justify-content:flex-end;gap:var(--s-2)">${iconBtn('edit', 'Edit ' + c[0])}<a class="btn btn-secondary btn-icon" style="width:36px;height:36px" href="#state=${c[0].startsWith('Brightwater') ? 'deleteblocked' : 'delete'}" aria-label="Delete ${c[0]}">${icon('trash', 16)}</a></div></td></tr>`).join('');
  const cards = CUST.slice(0, 3).map((c) => `<article class="card task-card"><div class="t-sub">${c[0]}</div><div class="t-body t-muted">${c[1]}</div><a class="btn btn-secondary" href="#state=edit">${icon('edit', 18)} Edit</a></article>`).join('');
  const rateRows = PROC.map((p, i) => { const own = { 0: '0.50', 2: '2.50', 7: '1.05' }[i]; return `<tr><th scope="row" style="text-transform:none;letter-spacing:0;font-size:var(--fs-body);color:var(--ink);background:none">${esc(p[0])}</th><td class="num t-muted">${fmt(p[2])}</td><td style="min-width:150px"><label class="sr-only" for="cr${i}">${esc(p[0])} for Brightwater Controls</label><div class="input-group"><input class="input" id="cr${i}" inputmode="decimal" value="${own || fmt(p[2])}" style="height:36px"><span class="addon">${p[1] === '%' ? '%' : '₹'}</span></div></td><td>${own ? `<span class="badge badge-warn">${icon('flag', 12)} Differs from default</span>` : '<span class="t-label t-muted">Same as default</span>'}</td></tr>`; }).join('');
  const main = `<main class="page" id="main">
   <div data-show="default loading empty error nomatch delete deleteblocked" data-hide="edit new reset">${pageHead({ title: 'Customers', sub: 'Each customer has its own value for every process rate.', actions: `<a class="btn btn-primary" href="#state=new">${icon('plus', 18)} Add customer</a>` })}</div>
   <div data-show="edit reset" hidden>${crumbs([['Customers', '#state=default'], ['Brightwater Controls']])}${pageHead({ title: 'Brightwater Controls', sub: '3 rates differ from the defaults.', actions: `<a class="btn btn-secondary" href="#state=reset">${icon('undo', 18)} Reset to defaults</a>` })}</div>
   <div data-show="new" hidden>${crumbs([['Customers', '#state=default'], ['New customer']])}${pageHead({ title: 'New customer', sub: 'All rates start at the current defaults.' })}</div>
   <section class="card" data-show="default nomatch delete deleteblocked" ><div class="card-body row" style="align-items:flex-end">${search('Customer name')}</div><div class="table-wrap is-master hide-mobile" data-show="default delete deleteblocked" ><table class="table"><caption class="sr-only">Customers</caption><thead><tr><th scope="col">Customer</th><th scope="col">Phone</th><th scope="col" class="hide-md">E-mail</th><th scope="col" class="num">Rates</th><th scope="col" class="col-actions"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows}</tbody></table></div><div class="stack show-mobile" style="padding:var(--s-4)" data-show="default delete deleteblocked">${cards}</div><div data-show="nomatch" hidden>${emptyState({ ic: 'search', title: 'No customer matches "kaveri"', text: 'Check the spelling or add the customer.', action: '<a class="btn btn-primary" href="#state=new">' + icon('plus', 18) + ' Add customer</a>' })}</div></section>
   <div data-show="loading" hidden class="card" aria-busy="true"><p class="sr-only" role="status">Loading customers</p>${skeletonRows(5, 4)}</div>
   <div data-show="empty" hidden class="card">${emptyState({ ic: 'users', title: 'No customers yet', text: 'Add the first customer. It starts with every default rate.', action: `<a class="btn btn-primary" href="#state=new">${icon('plus', 18)} Add customer</a>` })}</div>
   <div data-show="error" hidden class="card">${emptyState({ ic: 'alert', title: 'We could not load customers', text: 'Check your connection and try again.', action: '<button class="btn btn-secondary" type="button">' + icon('undo', 18) + ' Try again</button>' })}</div>
   <div data-show="edit new reset" hidden class="stack-lg">
    <section class="card" aria-labelledby="c-t"><div class="card-head"><h2 id="c-t" class="t-sub">Details</h2></div><div class="card-body grid-fields" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">
     ${field({ id: 'c-name', label: 'Customer name', value: 'Brightwater Controls' })}${field({ id: 'c-phone', label: 'Phone', value: '+91 98765 00001', required: false, mode: 'tel' })}${field({ id: 'c-mail', label: 'E-mail', type: 'email', value: 'purchasing@brightwater.example.test', required: false })}${field({ id: 'c-addr', label: 'Address', value: 'Plot 14, Industrial Estate, Sample City', required: false, wide: true })}</div></section>
    <section class="card" aria-labelledby="r-t"><div class="card-head"><h2 id="r-t" class="t-sub">Rates for this customer</h2><span class="spacer"></span><span class="t-label t-muted">Percent rates are whole numbers: 11 means 11%</span></div>
     <div class="table-wrap"><table class="table"><thead><tr><th scope="col">Rate</th><th scope="col" class="num">Default</th><th scope="col">This customer</th><th scope="col">Status</th></tr></thead><tbody>${rateRows}</tbody></table></div>
     <div class="card-foot"><a class="btn btn-secondary" href="#state=default">Cancel</a><span class="spacer"></span><button class="btn btn-primary" type="button">Save customer</button></div></section></div>
   ${dlg('delete', 'Delete Marlow Agro Systems?', 'trash', `<p class="t-body">Marlow Agro Systems no longer appears in this list or in the customer choice on new estimates. Estimates that are already calculated keep their figures. You cannot undo this here.</p>`, `<a class="btn btn-secondary" href="#state=default">Keep customer</a><button class="btn btn-danger" type="button">${icon('trash', 18)} Delete customer</button>`, { role: 'alertdialog' })}
   ${dlg('deleteblocked', 'Brightwater Controls cannot be deleted yet', 'alert', `<p class="t-body">An open estimate uses this customer:</p><ul class="stack-sm" style="list-style:disc;padding-left:var(--s-5)"><li><a href="SCR-06.html">Q-2026-0318</a>, Control cabinet CC-40 (Submitted)</li></ul><p class="t-body">Approve it, or move it to another customer, and then delete this one.</p>`, `<a class="btn btn-primary" href="#state=default">Close</a>`, { role: 'alertdialog' })}
   ${dlg('reset', 'Reset Brightwater Controls to defaults?', 'undo', `<p class="t-body">All 15 rates return to the current Process master values. The 3 values this customer has now (Cutting-Rate-per-Sec 0.50, Drilling-Tapping-Rate 2.50, Polishing-rate-per-sqin 1.05) are replaced. Approved estimates are not affected.</p>`, `<a class="btn btn-secondary" href="#state=edit">Keep current rates</a><button class="btn btn-primary" type="button">${icon('undo', 18)} Reset to defaults</button>`, { role: 'alertdialog' })}
   ${reviewNote('Release 1. "Reset to defaults" always asks first (FR-013). Phone: the rate table scrolls inside its own container; the customer list becomes cards. Phone, address and e-mail are optional in this design (only the name is required); that is a proposal (OQ-UX-04). The name must be unique: "A customer with this name already exists."')}
  </main>`;
  return page({ id: 'SCR-12', file: 'SCR-12.html', name: 'Customer master', title: 'Customers', desc: 'Manage customers and their rates for Accucut cost estimates.', role: 'admin', active: 'customers', states: ['default:List', 'edit:Edit customer', 'new:New customer', 'reset:Reset dialog', 'delete:Delete', 'deleteblocked:Delete blocked', 'loading', 'empty', 'nomatch:No match', 'error'], roleLabel: 'Admin', release: 'R1', frs: 'FR-013', body: main });
}

/* ============================ SCR-13 Materials, FX, lists ============================ */
function scr13() {
  const matRows = [MAT.MS, MAT.SS, MAT.AL].map((m) => `<tr><td class="t-strong">${m.name}</td><td>${m.considered}</td><td class="num">${fmt(m.price)}</td><td class="num">${fmt(m.sg)}</td><td class="num">${fmt(m.scrap)}</td><td class="t-right col-actions"><div class="row" style="justify-content:flex-end;gap:var(--s-2)">${iconBtn('edit', 'Edit ' + m.name)}<a class="btn btn-secondary btn-icon" style="width:36px;height:36px" href="#state=${m === MAT.MS ? 'deleteblocked' : 'delete'}" aria-label="Delete ${m.name}">${icon('trash', 16)}</a></div></td></tr>`).join('');
  const matCards = [MAT.MS, MAT.SS].map((m) => `<article class="card task-card"><div class="t-sub">${m.name}</div><div class="t-body t-muted">${m.considered} &middot; ₹ ${fmt(m.price)} per kg</div><button class="btn btn-secondary" type="button">${icon('edit', 18)} Edit</button></article>`).join('');
  const treat = ['Textured grey', 'Brushed finish', 'Anodised natural'].map((t) => `<tr><td class="t-strong">${t}</td><td class="t-right col-actions"><div class="row" style="justify-content:flex-end;gap:var(--s-2)">${iconBtn('edit', 'Rename ' + t)}${iconBtn('trash', 'Delete ' + t)}</div></td></tr>`).join('') + `<tr class="is-locked"><td class="t-strong">Other ${lockTag('Always available')}</td><td class="t-right col-actions"><span class="t-label t-muted">${icon('lock', 12)} Always offered; the Engineer types the text</span></td></tr>`;
  const tabs = `<div class="tabs" role="tablist" aria-label="Lists" data-tabs="#main"><button class="tab is-active" role="tab" id="tab-m" aria-controls="p-m" aria-selected="true" type="button">Materials</button><button class="tab" role="tab" id="tab-x" aria-controls="p-x" aria-selected="false" tabindex="-1" type="button">Exchange rates</button><button class="tab" role="tab" id="tab-t" aria-controls="p-t" aria-selected="false" tabindex="-1" type="button">Treatment / Color</button></div>`;
  const main = `<main class="page" id="main">
   ${pageHead({ title: 'Materials and lists', sub: 'Material prices, exchange rates and the treatment and colour list.' })}
   <section class="card"><div class="card-body">${tabs}</div>
    <div role="tabpanel" id="p-m" aria-labelledby="tab-m"><div style="padding:0 var(--s-5) var(--s-3)" class="row"><span style="flex:1"></span><button class="btn btn-primary" type="button">${icon('plus', 18)} Add material</button></div>
     <div data-show="default dup saved delete deleteblocked"><div class="table-wrap is-master hide-mobile"><table class="table"><caption class="sr-only">Material Master</caption><thead><tr><th scope="col">Material in Drawing</th><th scope="col">Material Considered</th><th scope="col" class="num">Price per kg (₹)</th><th scope="col" class="num">Specific gravity</th><th scope="col" class="num">Material-Scrap-Rate (₹ per kg)</th><th scope="col" class="col-actions"><span class="sr-only">Actions</span></th></tr></thead><tbody>${matRows}</tbody></table></div><div class="stack show-mobile" style="padding:var(--s-4)">${matCards}</div></div>
     ${loadingBlock(4, 5)}${errorBlock('the materials')}</div>
    <div role="tabpanel" id="p-x" aria-labelledby="tab-x" hidden><div class="card-body stack" style="max-width:560px">
     ${field({ id: 'fx-usd', label: '1 US dollar in rupees', unit: '₹', mode: 'decimal', value: fmt(L.FX.usd), hint: 'Converts prices to US dollars. The rate (BH) feeds Unit Production Price (USD), BJ.' })}${field({ id: 'fx-eur', label: '1 euro in rupees', unit: '₹', mode: 'decimal', value: fmt(L.FX.eur), hint: 'Converts prices to euros. The rate (BI) feeds Unit Production Price (EUR), BK.' })}
     <p class="t-label t-muted">Last updated by Meera Iyer, 02 Nov 2026, 15:10 IST.</p><div class="row"><button class="btn btn-primary" type="button">Save exchange rates</button></div></div></div>
    <div role="tabpanel" id="p-t" aria-labelledby="tab-t" hidden><div style="padding:0 var(--s-5) var(--s-3)" class="row"><span style="flex:1"></span><button class="btn btn-primary" type="button">${icon('plus', 18)} Add treatment or colour</button></div><div class="table-wrap is-master"><table class="table"><caption class="sr-only">Treatment and colour list</caption><thead><tr><th scope="col">Name</th><th scope="col" class="col-actions"><span class="sr-only">Actions</span></th></tr></thead><tbody>${treat}</tbody></table></div></div></section>
   ${dlg('dup', 'Add material', 'plus', `${field({ id: 'm-name', label: 'Material in Drawing', value: 'MS sheet, cold rolled', error: 'A material with this name already exists. Names must be unique.' })}${field({ id: 'm-cons', label: 'Material Considered', value: 'Mild steel' })}<div class="grid-2">${field({ id: 'm-price', label: 'Price per kg', unit: '₹', mode: 'decimal', value: '58.00' })}${field({ id: 'm-sg', label: 'Specific gravity', mode: 'decimal', value: '7.85', hint: 'Must be above 0.' })}</div>${field({ id: 'm-scrap', label: 'Material-Scrap-Rate (per kg)', unit: '₹', mode: 'decimal', value: '22.00' })}`, `<button class="btn btn-secondary" type="button">Cancel</button><button class="btn btn-primary" type="button">Add material</button>`)}
   ${dlg('sg', 'Add material', 'plus', `${field({ id: 'm-name', label: 'Material in Drawing', value: 'Brass sheet' })}${field({ id: 'm-cons', label: 'Material Considered', value: 'Brass' })}<div class="grid-2">${field({ id: 'm-price', label: 'Price per kg', unit: '₹', mode: 'decimal', value: '58.00' })}${field({ id: 'm-sg', label: 'Specific gravity', mode: 'decimal', value: '7.85', value: '0', hint: 'Must be above 0.', error: 'Enter a value above 0.' })}</div>${field({ id: 'm-scrap', label: 'Material-Scrap-Rate (per kg)', unit: '₹', mode: 'decimal', value: '22.00' })}`, `<button class="btn btn-secondary" type="button">Cancel</button><button class="btn btn-primary" type="button">Add material</button>`)}
   ${dlg('delete', 'Delete AL sheet, 5-series?', 'trash', `<p class="t-body">This material no longer appears in the Material in Drawing list. Estimates that are already calculated keep their figures.</p>`, `<a class="btn btn-secondary" href="#state=default">Keep material</a><button class="btn btn-danger" type="button">${icon('trash', 18)} Delete material</button>`, { role: 'alertdialog' })}
   ${dlg('deleteblocked', 'MS sheet, cold rolled cannot be deleted yet', 'alert', `<p class="t-body">An open estimate uses this material:</p><ul class="stack-sm" style="list-style:disc;padding-left:var(--s-5)"><li><a href="SCR-06.html">Q-2026-0318</a>, Control cabinet CC-40 (Submitted)</li></ul><p class="t-body">Approve it, or change the material on its parts, and then delete this one.</p>`, `<a class="btn btn-primary" href="#state=default">Close</a>`, { role: 'alertdialog' })}
   ${reviewNote('Release 1. <strong>"Not applicable" is not listed on this screen or on any master list</strong> (their words, AQP-1 10490, as settled in Q-36: it shows on a part, not in the lists). The system keeps it with all values 0 and offers it as a choice in the Material in Drawing and Treatment / Color drop-downs of the estimate form (FR-018); nobody can edit, rename or delete it. Everyone sees the words "Not applicable" on a part that has it, and Material Rate and Material Considered stay blank for it (Q-36, settled); see SCR-05, 06 and 07. "Other" is always offered in the treatment list and cannot be removed (FR-017). Material rates are never sent to Engineers.')}
  </main>`;
  return page({ id: 'SCR-13', file: 'SCR-13.html', name: 'Materials, exchange rates, treatment list', title: 'Materials and lists', desc: 'Manage materials, exchange rates and the treatment and colour list used in estimates.', role: 'admin', active: 'materials', states: ['default', 'dup:Duplicate name', 'sg:Specific gravity 0', 'delete:Delete', 'deleteblocked:Delete blocked', 'loading', 'error'], roleLabel: 'Admin', release: 'R1', frs: 'FR-015, 016, 017, 018', body: main });
}

